    public function konversiTanggal($tanggal)
    {
        $tahun = substr($tanggal, 0, 4);
        $bulan = substr($tanggal, 5, 2);
        $bulan_string = '';
        $tanggal = substr($tanggal, 8, 2);

        switch ($bulan) {
            case '01':
                $bulan_string = 'Januari';
                break;

            case '02':
                $bulan_string = 'Februari';
                break;

            case '03':
                $bulan_string = 'Maret';
                break;

            case '04':
                $bulan_string = 'April';
                break;

            case '05':
                $bulan_string = 'Mei';
                break;

            case '06':
                $bulan_string = 'Juni';
                break;

            case '07':
                $bulan_string = 'Juli';
                break;

            case '08':
                $bulan_string = 'Agustus';
                break;

            case '09':
                $bulan_string = 'September';
                break;

            case '10':
                $bulan_string = 'Oktober';
                break;

            case '11':
                $bulan_string = 'November';
                break;

            case '12':
                $bulan_string = 'Desember';
                break;

            default:
                $bulan_string = 'Bulan';
                break;
        }

        return $tanggal . " " . $bulan_string . " " . $tahun;
    }

