    function konversiAngkaRomawi($number)
    {
        if (is_numeric($number)) {
            $map = array('M' => 1000, 'CM' => 900, 'D' => 500, 'CD' => 400, 'C' => 100, 'XC' => 90, 'L' => 50, 'XL' => 40, 'X' => 10, 'IX' => 9, 'V' => 5, 'IV' => 4, 'I' => 1);
            $returnValue = '';
            while ($number > 0) {
                foreach ($map as $roman => $int) {
                    if ($number >= $int) {
                        $number -= $int;
                        $returnValue .= $roman;
                        break;
                    }
                }
            }
            return $returnValue;
        } else {
            return $number;
        }
    }

    function penyebut($nilai)
    {
        $nilai = abs($nilai);
        $huruf = array("", "satu", "dua", "tiga", "empat", "lima", "enam", "tujuh", "delapan", "sembilan", "sepuluh", "sebelas");
        $temp = "";
        if ($nilai < 12) {
            $temp = " " . $huruf[$nilai];
        } else if ($nilai < 20) {
            $temp = $this->penyebut($nilai - 10) . " belas";
        } else if ($nilai < 100) {
            $temp = $this->penyebut($nilai / 10) . " puluh" . $this->penyebut($nilai % 10);
        } else if ($nilai < 200) {
            $temp = " seratus" . $this->penyebut($nilai - 100);
        } else if ($nilai < 1000) {
            $temp = $this->penyebut($nilai / 100) . " ratus" . $this->penyebut($nilai % 100);
        } else if ($nilai < 2000) {
            $temp = " seribu" . $this->penyebut($nilai - 1000);
        } else if ($nilai < 1000000) {
            $temp = $this->penyebut($nilai / 1000) . " ribu" . $this->penyebut($nilai % 1000);
        } else if ($nilai < 1000000000) {
            $temp = $this->penyebut($nilai / 1000000) . " juta" . $this->penyebut($nilai % 1000000);
        } else if ($nilai < 1000000000000) {
            $temp = $this->penyebut($nilai / 1000000000) . " milyar" . $this->penyebut(fmod($nilai, 1000000000));
        } else if ($nilai < 1000000000000000) {
            $temp = $this->penyebut($nilai / 1000000000000) . " trilyun" . $this->penyebut(fmod($nilai, 1000000000000));
        }
        return $temp;
    }

    function umurPasien($tglLahir)
    {
        $tanggal_lahir = date('Y-m-d', strtotime($tglLahir));
        $tglLahir = new \DateTime($tanggal_lahir);
        $sekarang = new \DateTime("today");
        if ($tglLahir > $sekarang) {
            return "0 tahun 0 bulan 0 hari";
        }
        $y = $sekarang->diff($tglLahir)->y;
        $m = $sekarang->diff($tglLahir)->m;
        $d = $sekarang->diff($tglLahir)->d;
        return $y . " tahun " . $m . " bulan " . $d . " hari";
    }

    function sanitizeFileName($fileName)
    {
        $sanitizedFileName = preg_replace('/[^A-Za-z0-9-]/', '', str_replace(' ', '-', $fileName));
        $sanitizedFileName = preg_replace('/-{2,}/', '-', $sanitizedFileName);
        $sanitizedFileName = strtolower($sanitizedFileName);

        return $sanitizedFileName;
    }

    function getBulanLalu(int $n)
    {
        $date = new \DateTime();
        $day  = $date->format('j');
        $date->modify('first day of this month')->modify('-' . $n . ' months');
        if ($day > $date->format('t')) {
            $day = $date->format('t');
        }
        $date->setDate(intval($date->format('Y')), intval($date->format('m')), intval($day));
        return $date->format('n');
    }


    function selisihTanggal($tgl1, $tgl2)
    {
        $month1 = \DateTime::createFromFormat('d/m/Y',  $tgl1)->format('m');
        $date1 = \DateTime::createFromFormat('d/m/Y',  $tgl1)->format('d');
        $year1 = \DateTime::createFromFormat('d/m/Y',  $tgl1)->format('Y');
        $month2 = \DateTime::createFromFormat('d/m/Y',  $tgl2)->format('m');
        $date2 = \DateTime::createFromFormat('d/m/Y',  $tgl2)->format('d');
        $year2 = \DateTime::createFromFormat('d/m/Y',  $tgl2)->format('Y');
        $jd1 = GregorianToJD(intval($month1), intval($date1), intval($year1));
        $jd2 = GregorianToJD(intval($month2), intval($date2), intval($year2));
        $selisih = $jd2 - $jd1;
        return $selisih;
    }

